    from collections import Counter, deque
    from itertools import permutations

    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            components.append((color, cells))

    frames = []
    frame_cells = set()
    frame_colors = set()
    for color, cells in components:
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        border = {(r, c) for r in range(r0, r1 + 1)
                  for c in range(c0, c1 + 1)
                  if r in (r0, r1) or c in (c0, c1)}
        if r1 - r0 >= 2 and c1 - c0 >= 2 and set(cells) == border:
            frames.append((color, cells, r0, r1, c0, c1))
            frame_cells.update(cells)
            frame_colors.add(color)

    counts = Counter()
    for color, cells in components:
        if len(cells) == 1 and cells[0] not in frame_cells and color not in frame_colors:
            counts[color] += 1

    # Each frame is filled on alternating interior cells. Match marker-color
    # singleton counts to the number of those cells.
    targets = []
    for _, _, r0, r1, c0, c1 in frames:
        ih, iw = r1 - r0 - 1, c1 - c0 - 1
        targets.append((ih * iw + 1) // 2)

    colors = list(counts)
    assignment = {}
    if len(colors) >= len(frames):
        best_cost = None
        for choice in permutations(colors, len(frames)):
            cost = sum(abs(counts[col] - target)
                       for col, target in zip(choice, targets))
            if best_cost is None or cost < best_cost:
                best_cost = cost
                assignment = {i: col for i, col in enumerate(choice)}

    out = [[0] * w for _ in range(h)]
    for color, cells, r0, r1, c0, c1 in frames:
        for r, c in cells:
            out[r][c] = color

    for i, (_, _, r0, r1, c0, c1) in enumerate(frames):
        if i not in assignment:
            continue
        fill = assignment[i]
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if ((r - r0 - 1) + (c - c0 - 1)) % 2 == 0:
                    out[r][c] = fill

    return out
